    "unitId": "n1:task-comprehension:2018-12:4:line-3",
    "text": "面談の日時は、もう少し人数が集まったら調整するとして、調査協力へのサインをもらう同意書を郵送しないとね。目標人数に達するのを待たずに、その二十名には発送しちゃおう。",
