    "unitId": "n1:task-comprehension:2018-12:6:line-1",
    "text": "一次登録で定員に空きがあれば、大学のウェブサイトから自分の学部の科目と同じように、オンライン上で自分で登録できますよ。一次の結果は今日からウェブサイトで公開されるので、登録するなら、その確認をしてからですね。希望者が定員を上回った場合は抽選になります。",
