    "text": "定員のある科目は聴講の制度は適用されません。前は先生に個別に相談して聴講を認めてもらう学生もいたようですけど。不公平になりますから、今はね。ちなみに、登録科目の単位数は上限を超えてませんよね。超えてると、登録はできませんから。",
